-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.lock_user_study()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  perform pg_advisory_xact_lock(hashtextextended('study:' || auth.uid()::text, 0));
  delete from public.review_undo where user_id = auth.uid() and created_at < now() - interval '48 hours';
end;
$function$;

grant execute on function public.lock_user_study() to service_role;
